var t=[{title:`Stretching static`,text:`O întindere statică ține blând un mușchi sau o articulație aproape de capătul amplitudinii confortabile. O întindere a gambei lângă un perete sau o întindere sprijinită a flexorilor șoldului, de exemplu, poate fi menținută pentru scurt timp fără săltări. Ar trebui să se simtă ca o tensiune ușoară, niciodată ca durere ascuțită sau amorțeală.`},{title:`Stretching dinamic`,text:`Stretchingul dinamic parcurge o amplitudine utilă din nou și din nou: balansări ale piciorului pe care le poți controla, cercuri cu brațele, fandări alternate. Fiecare repetare este deliberată, fără săltări sau grabă. Aceste exerciții se potrivesc firesc într-o încălzire pentru alergare, ridicări și sporturi.`},{title:`Când folosești fiecare`,text:`Înainte de un efort exploziv, mișcarea dinamică treptată și exersarea exercițiului în sine funcționează de obicei cel mai bine. Stretchingul static lung și intens chiar înainte poate reduce pentru scurt timp forța sau puterea, în timp ce câteva întinderi scurte ținute sunt mai puțin îngrijorătoare. După antrenament sau într-o sesiune separată, stretchingul static este o modalitate rezonabilă de a lucra la flexibilitate.`},{title:`Cât să faci`,text:`Folosește întinderi scurte și confortabile, ținute puțin, și repetă-le pe parcursul săptămânilor în loc să forțezi o amplitudine nouă într-o singură sesiune. La exercițiile dinamice, începe cu o amplitudine mică și lărgește-o doar cât mișcarea rămâne controlată. Stretchingul nu trebuie să doară ca să funcționeze, iar mai multă flexibilitate nu ajută la fiecare activitate.`},{title:`Ce nu poate promite stretchingul`,text:`Folosește exercițiile dinamice ca să te pregătești pentru mișcare activă și întinderile statice când flexibilitatea este scopul. Niciuna nu te face imun la accidentări și nu previne în mod fiabil durerea musculară. Dacă durerea persistă, cere unui medic sau unui fizioterapeut un sfat potrivit pentru tine.`}];var r=[{label:`ACE 2026: ghid practic despre stretching`,url:`https://www.acefitness.org/continuing-education/certified/april-2026/9104/new-expert-guidance-on-stretching-what-belongs-in-your-programs/?authorScope=80`},{label:`ACE 2026: mobilitate versus flexibilitate`,url:`https://www.acefitness.org/continuing-education/certified/may-2026/9119/mobility-vs-flexibility-why-the-difference-matters-for-movement-and-performance/`},{label:`NHS: exerciții blânde de revenire`,url:`https://www.nhs.uk/live-well/exercise/strength-and-resistance/body-blast-cool-down/`}];var a={sections:t,sources:r};export{a as default,t as sections,r as sources};